package app.p3r.dayplanner.v2;
import android.content.Context;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class PlayerStateFormTest {
 private Context context;private PlayerStateForm form;
 private JSONObject read(String name)throws Exception{try(InputStream in=context.getAssets().open("planner_v2/rules_v04/"+name)){return new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}}
 private Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 @Before public void setup()throws Exception{context=RuntimeEnvironment.getApplication();JSONObject baseline=new JSONObject().put("game_slot",552).put("cash",JSONObject.NULL).put("highest_floor",JSONObject.NULL).put("active_stage","p3r.tower.stage_10").put("visits_by_stage",new JSONObject().put("p3r.tower.stage_10",JSONObject.NULL)).put("facts",new JSONObject().put("stats.academics",new JSONObject().put("low",57).put("high",80)));
  form=new PlayerStateForm(context,baseline,read("social_links.json").getJSONArray("entities"),read("tower_stages.json").getJSONArray("stages"),read("stats_actions.json").getJSONArray("statRules"));Map<?,?> links=(Map<?,?>)field(form,"links");((CheckBox)field(links.get("sun"),"goal")).setChecked(true);}
 @Test public void allGoalsAndUnknownStateStayExplicit()throws Exception{assertEquals(22,((Map<?,?>)field(form,"links")).size());JSONObject result=form.collect("test-rules");JSONObject baseline=result.getJSONObject("baseline");assertTrue(baseline.isNull("cash"));assertTrue(baseline.getJSONObject("visits_by_stage").isNull("p3r.tower.stage_10"));assertTrue(baseline.getJSONObject("facts").getJSONObject("socialLinks.sun.rank").isNull("low"));assertEquals(1,result.getJSONArray("goals").length());}
 @Test public void unchangedVisibleStatRankRetainsObservedInterval()throws Exception{JSONObject stat=form.collect("test-rules").getJSONObject("baseline").getJSONObject("facts").getJSONObject("stats.academics");assertEquals(57,stat.getInt("low"));assertEquals(80,stat.getInt("high"));JSONObject old=((JSONObject)field(form,"original")).getJSONObject("facts").getJSONObject("stats.academics");assertEquals(57,old.getInt("low"));assertEquals(80,old.getInt("high"));}
 @Test public void priorityAndOtherStageCapsSurvive()throws Exception{form.loadPreferences(new JSONObject().put("goals",new JSONArray().put(new JSONObject().put("field","socialLinks.sun.rank").put("target",10).put("priority",7))).put("constraints",new JSONObject().put("visit_caps",new JSONObject().put("p3r.tower.stage_01",2))));JSONObject result=form.collect("test-rules");assertEquals(7,result.getJSONArray("goals").getJSONObject(0).getInt("priority"));assertEquals(2,result.getJSONObject("constraints").getJSONObject("visit_caps").getInt("p3r.tower.stage_01"));}
 @Test(expected=IllegalArgumentException.class) public void invalidRankRejected()throws Exception{Object link=((Map<?,?>)field(form,"links")).get("sun");((EditText)field(link,"rank")).setText("11");form.collect("test-rules");}
 @Test public void all22CatalogGoalsCanBeSelectedWithTheirPriorities()throws Exception {
  Map<?,?> links=(Map<?,?>)field(form,"links");int priority=0;
  for(Object link:links.values()){((CheckBox)field(link,"goal")).setChecked(true);((EditText)field(link,"priority")).setText(""+priority++);}
  JSONArray goals=form.collect("test-rules").getJSONArray("goals");assertEquals(22,goals.length());for(int n=0;n<22;n++)assertEquals(n,goals.getJSONObject(n).getInt("priority"));
 }
 @Test public void unknownHiddenAffinityUsesConservativeIntervalWithoutVisibleInput()throws Exception {
  Object sun=((Map<?,?>)field(form,"links")).get("sun");assertNull(((EditText)field(sun,"affinity")).getParent());assertNull(((CheckBox)field(form,"answerAssumption")).getParent());
  ((EditText)field(sun,"rank")).setText("4");((Spinner)field(sun,"normal")).setSelection(1);((EditText)field(sun,"affinity")).setText("200");
  JSONObject result=form.collect("test-rules");JSONObject facts=result.getJSONObject("baseline").getJSONObject("facts");
  assertEquals(0,facts.getJSONObject("socialLinks.sun.affinityLowerBound").getInt("low"));assertTrue(facts.getJSONObject("socialLinks.sun.affinityLowerBound").isNull("high"));assertFalse(result.getJSONObject("baseline").getJSONObject("option_policy").optBoolean("declared"));
 }
 @Test public void changedRankCannotRetainReadinessForOldRank()throws Exception {
  Object sun=((Map<?,?>)field(form,"links")).get("sun");((EditText)field(sun,"rank")).setText("4");((Spinner)field(sun,"normal")).setSelection(1);((Spinner)field(sun,"ready")).setSelection(1);((EditText)field(sun,"rank")).setText("5");
  JSONObject facts=form.collect("test-rules").getJSONObject("baseline").getJSONObject("facts");assertTrue(facts.getJSONObject("socialLinks.sun.ready").isNull("low"));assertTrue(facts.getJSONObject("socialLinks.sun.readyRank").isNull("low"));
 }
 @Test public void calendarSupportsOctoberAndJanuaryWithoutDeviceYear()throws Exception {
  ((EditText)field(form,"month")).setText("10");((EditText)field(form,"day")).setText("22");((Spinner)field(form,"phase")).setSelection(1);assertEquals(GameDate.slot(10,22,true),form.collect("test-rules").getJSONObject("baseline").getInt("game_slot"));
  ((EditText)field(form,"month")).setText("1");((EditText)field(form,"day")).setText("10");assertEquals(GameDate.slot(1,10,true),form.collect("test-rules").getJSONObject("baseline").getInt("game_slot"));
 }
 @Test public void romanceIntentAndActualRelationshipStateRemainDistinct()throws Exception {
  Object justice=((Map<?,?>)field(form,"links")).get("justice");((EditText)field(justice,"rank")).setText("5");((Spinner)field(justice,"normal")).setSelection(2);((Spinner)field(justice,"ready")).setSelection(1);((Spinner)field(justice,"relationshipType")).setSelection(1);((Spinner)field(justice,"romanceEligible")).setSelection(1);((Spinner)field(justice,"relationshipDecision")).setSelection(2);
  JSONObject b=form.collect("test-rules").getJSONObject("baseline");assertEquals("friendship",b.getJSONObject("planning_context").getJSONObject("socialLinks").getJSONObject("justice").getString("relationshipType"));assertEquals("romantic",b.getJSONObject("option_policy").getJSONObject("relationship_decisions").getString("justice"));assertTrue(b.getJSONObject("facts").getJSONObject("socialLinks.justice.ready").isNull("low"));
 }
 @Test public void julyManualGapDoesNotInventAStageOrResetHistoricalCounts()throws Exception {
  form.setOperationalStageWindows(new NativeProgressionRules(context).stageWindows());((Spinner)field(form,"stage")).setSelection(0);((EditText)field(form,"month")).setText("7");
  ((JSONObject)field(form,"original")).getJSONObject("visits_by_stage").put("p3r.tower.stage_03",2);
  for(int d=9;d<=17;d++){((EditText)field(form,"day")).setText(""+d);JSONObject b=form.collect("test-rules").getJSONObject("baseline");assertTrue("July "+d,b.isNull("active_stage"));assertEquals(2,b.getJSONObject("visits_by_stage").getInt("p3r.tower.stage_03"));assertFalse(b.getJSONObject("visits_by_stage").has("p3r.tower.stage_04"));}
  ((EditText)field(form,"used")).setText("1");try{form.collect("test-rules");fail("Unknown-stage count must not be assigned automatically");}catch(IllegalArgumentException expected){}
 }
 @Test public void checkedStudyAndCafeAreExplicitWhileSecretMenusRemainAbsent()throws Exception {
  form.addTrainingAvailability();@SuppressWarnings("unchecked") Map<CheckBox,String[]> access=(Map<CheckBox,String[]>)field(form,"trainingAccess");assertEquals(8,access.size());
  for(Map.Entry<CheckBox,String[]> e:access.entrySet())e.getKey().setChecked(Arrays.asList(e.getValue()).contains("study_room_night")||Arrays.asList(e.getValue()).contains("coffee_chagall_night"));
  ((Spinner)field(form,"currentCapacity")).setSelection(1);JSONObject b=form.collect("test-rules").getJSONObject("baseline"),context=b.getJSONObject("planning_context");JSONObject guards=context.getJSONObject("progression").getJSONObject("repeatableActivityGuards");assertEquals(2,guards.length());assertTrue(guards.getJSONObject("study_room_night").getBoolean("locationAccessible"));assertTrue(guards.getJSONObject("coffee_chagall_night").getBoolean("locationAccessible"));JSONObject current=context.getJSONObject("calendar").getJSONObject("statActionStates").getJSONObject(""+b.getInt("game_slot"));assertEquals(2,current.length());assertTrue(current.getJSONObject("study_room_night").getBoolean("calendar.exactDateActionAvailable"));assertFalse(guards.toString().contains("secret"));assertFalse(guards.has("meal_wakatsu_special"));
 }
 @Test public void devilPreparationRetainsCurrentFlagsUntilDateChanges()throws Exception {
  JSONObject old=(JSONObject)field(form,"original");old.put("planning_context",new JSONObject().put("unlock",new JSONObject().put("devil",new JSONObject().put("stage","paid2").put("lastPaymentDate",100).put("observations",new JSONObject().put("current.devil.payment_interaction_available",true)))));
  form.addUnlockPreparation(new NativeUnlockRules(context).preparationFormSchema());Object devil=((Map<?,?>)field(form,"links")).get("devil");Spinner stage=(Spinner)field(devil,"preparation");JSONArray options=(JSONArray)field(devil,"preparationOptions");assertEquals("paid2",options.getJSONObject(stage.getSelectedItemPosition()).getString("value"));
  JSONObject collected=form.collect("test-rules").getJSONObject("baseline").getJSONObject("planning_context").getJSONObject("unlock").getJSONObject("devil");assertEquals("paid2",collected.getString("stage"));assertTrue(collected.getJSONObject("observations").getBoolean("current.devil.payment_interaction_available"));assertEquals(100,collected.getInt("lastPaymentDate"));form.organizeSections();((EditText)field(form,"day")).setText("11");collected=form.collect("test-rules").getJSONObject("baseline").getJSONObject("planning_context").getJSONObject("unlock").getJSONObject("devil");assertTrue(collected.getJSONObject("observations").isNull("current.devil.payment_interaction_available"));
  stage.setSelection(0);collected=form.collect("test-rules").getJSONObject("baseline").getJSONObject("planning_context").getJSONObject("unlock").getJSONObject("devil");assertTrue(collected.isNull("stage"));assertFalse(collected.has("lastPaymentDate"));
 }
 @Test public void towerObservationIsDatedAndPaidWorkRequiresExplicitAccess()throws Exception {
  form.addTrainingAvailability();((Spinner)field(form,"phase")).setSelection(1);((Spinner)field(form,"towerEntry")).setSelection(1);((CheckBox)field(form,"towerRoutine")).setChecked(true);
  @SuppressWarnings("unchecked") Map<CheckBox,String[]> access=(Map<CheckBox,String[]>)field(form,"trainingAccess");for(Map.Entry<CheckBox,String[]> e:access.entrySet())if(Arrays.asList(e.getValue()).contains("job_chagall_minimum"))e.getKey().setChecked(true);
  JSONObject b=form.collect("test-rules").getJSONObject("baseline"),p=b.getJSONObject("planning_context"),tower=p.getJSONObject("tartarus");assertTrue(tower.getBoolean("entryAvailableObserved"));assertEquals(b.getInt("game_slot")/2,tower.getInt("entryObservationDateOrdinal"));assertEquals("evening",tower.getString("entryObservationSlot"));assertTrue(tower.getBoolean("assumeRoutineFutureEntry"));assertTrue(p.getJSONObject("progression").getJSONObject("repeatableActivityGuards").getJSONObject("job_chagall_minimum").getBoolean("locationAccessible"));
 }
 private JSONObject exactValue(int n)throws Exception{return new JSONObject().put("low",n).put("high",n);}
 private PlayerStateForm rebuild(JSONObject baseline)throws Exception{return new PlayerStateForm(context,baseline,read("social_links.json").getJSONArray("entities"),read("tower_stages.json").getJSONArray("stages"),read("stats_actions.json").getJSONArray("statRules"));}
 @Test public void unchangedCanonicalStatsAffinityAndCapacitySurviveReopen()throws Exception{JSONObject b=new JSONObject(((JSONObject)field(form,"original")).toString());JSONObject facts=b.getJSONObject("facts");facts.remove("stats.academics");facts.put("socialStats.academics.raw",new JSONObject().put("low",57).put("high",80)).put("socialStats.academics.rank",exactValue(3)).put("socialLinks.sun.rank",exactValue(4)).put("socialLinks.sun.normal",exactValue(1)).put("socialLinks.sun.affinityLowerBound",new JSONObject().put("low",8).put("high",JSONObject.NULL)).put("socialLinks.sun.affinityRank",exactValue(4)).put("socialLinks.sun.affinityValid",exactValue(1));b.put("planning_context",new JSONObject().put("calendar",new JSONObject().put("slotStates",new JSONObject().put("552",new JSONObject().put("remainingCapacity",1)))));form=rebuild(b);Object sun=((Map<?,?>)field(form,"links")).get("sun");((CheckBox)field(sun,"goal")).setChecked(true);assertEquals(1,((Spinner)field(form,"currentCapacity")).getSelectedItemPosition());assertEquals(3,((Spinner)((Map<?,?>)field(form,"stats")).get("academics")).getSelectedItemPosition());JSONObject out=form.collect("test").getJSONObject("baseline");assertEquals(8,out.getJSONObject("facts").getJSONObject("socialLinks.sun.affinityLowerBound").getInt("low"));assertEquals(57,out.getJSONObject("facts").getJSONObject("socialStats.academics.raw").getInt("low"));assertEquals(80,out.getJSONObject("facts").getJSONObject("socialStats.academics.raw").getInt("high"));assertEquals(1,out.getJSONObject("planning_context").getJSONObject("calendar").getJSONObject("slotStates").getJSONObject("552").getInt("remainingCapacity"));((EditText)field(sun,"rank")).setText("5");assertEquals(0,form.collect("test").getJSONObject("baseline").getJSONObject("facts").getJSONObject("socialLinks.sun.affinityLowerBound").getInt("low"));}
 @Test public void priorPreparationTimingDistinguishesUnknownBeforeAndToday()throws Exception{form.addUnlockPreparation(new NativeUnlockRules(context).preparationFormSchema());Object devil=((Map<?,?>)field(form,"links")).get("devil");JSONArray choices=(JSONArray)field(devil,"preparationOptions");for(int i=0;i<choices.length();i++)if("paid2".equals(choices.getJSONObject(i).optString("value")))((Spinner)field(devil,"preparation")).setSelection(i);for(int timing:new int[]{0,1,2}){((Spinner)field(devil,"preparationTiming")).setSelection(timing);JSONObject b=form.collect("test").getJSONObject("baseline"),p=b.getJSONObject("planning_context").getJSONObject("unlock").getJSONObject("devil");assertEquals("paid2",p.getString("stage"));assertEquals(b.getInt("game_slot")/2-(timing==1?1:0),p.getInt("lastPossiblePrepOrdinal"));assertFalse(p.has("lastPaymentDate"));}}
 @Test public void rawDraftRetainsUnknownZeroAndIncompleteInput()throws Exception{((EditText)field(form,"cash")).setText("0");((EditText)field(form,"day")).setText("");JSONObject draft=form.exportDraft();PlayerStateForm restored=rebuild((JSONObject)field(form,"original"));assertTrue(restored.restoreDraft(draft));assertEquals("0",((EditText)field(restored,"cash")).getText().toString());assertEquals("",((EditText)field(restored,"day")).getText().toString());assertFalse(restored.restoreDraft(new JSONObject().put("schema","wrong").put("values",new JSONArray())));}
}
